DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.apply_plan_edit(uuid,jsonb,uuid,text)'::regprocedure) INTO def; def:=replace(def,'verification_price_thb=newrow.verification_price_thb,','verification_price_thb=newrow.verification_price_thb,verification_business_days=newrow.verification_business_days,verification_recheck_business_days=newrow.verification_recheck_business_days,verification_vat_pct=newrow.verification_vat_pct,'); EXECUTE def; END $$;
CREATE OR REPLACE FUNCTION public.verification_plan_timing_validate() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.verification_business_days<1 OR NEW.verification_recheck_business_days<1 OR NEW.verification_vat_pct<0 OR NEW.verification_vat_pct>100 THEN RAISE EXCEPTION 'Use positive business days and VAT between 0 and 100'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER verification_plan_timing_validate BEFORE INSERT OR UPDATE OF verification_business_days,verification_recheck_business_days,verification_vat_pct ON public.plans FOR EACH ROW EXECUTE FUNCTION public.verification_plan_timing_validate();